-- =====================================================================
-- JobTrack - 01_schema.sql  (PostgreSQL / Supabase)
-- Chạy trong Supabase: SQL Editor → dán toàn bộ file → Run
-- Chạy lại được nhiều lần (xoá bảng cũ trước) → CHÚ Ý: dữ liệu bị xoá hết
--
-- Khác với bản MySQL (database/schema.sql):
--   AUTO_INCREMENT          → BIGINT GENERATED BY DEFAULT AS IDENTITY
--   DATETIME                → TIMESTAMP
--   ON UPDATE CURRENT_TIMESTAMP → trigger set_updated_at()
--   KEY ...                 → CREATE INDEX
--   ENGINE / CHARSET        → không cần (PostgreSQL mặc định UTF-8)
--   + bảng SPRING_SESSION   → lưu session trong DB (Vercel tắt app khi không có truy cập)
-- =====================================================================

DROP TABLE IF EXISTS spring_session_attributes CASCADE;
DROP TABLE IF EXISTS spring_session CASCADE;
DROP TABLE IF EXISTS part_time_shifts CASCADE;
DROP TABLE IF EXISTS ai_results CASCADE;
DROP TABLE IF EXISTS tasks CASCADE;
DROP TABLE IF EXISTS interviews CASCADE;
DROP TABLE IF EXISTS applications CASCADE;
DROP TABLE IF EXISTS companies CASCADE;
DROP TABLE IF EXISTS users CASCADE;

-- updated_at tự cập nhật khi UPDATE (thay cho ON UPDATE CURRENT_TIMESTAMP của MySQL)
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- ---------------------------------------------------------------------
-- 1. users : tài khoản đăng nhập
-- ---------------------------------------------------------------------
CREATE TABLE users (
    id             BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name           VARCHAR(50)  NOT NULL,
    email          VARCHAR(255) NOT NULL,
    password_hash  VARCHAR(255) NOT NULL,                 -- BCrypt (60 ký tự)
    created_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_users_email UNIQUE (email)
);

-- ---------------------------------------------------------------------
-- 2. companies
-- ---------------------------------------------------------------------
CREATE TABLE companies (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT       NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name        VARCHAR(100) NOT NULL,
    industry    VARCHAR(50)  NULL,
    url         VARCHAR(255) NULL,
    memo        TEXT         NULL,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_companies_user_name UNIQUE (user_id, name)
);

-- ---------------------------------------------------------------------
-- 3. applications (không có user_id: chủ sở hữu qua company → user)
-- ---------------------------------------------------------------------
CREATE TABLE applications (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    company_id  BIGINT       NOT NULL REFERENCES companies (id) ON DELETE CASCADE,
    position    VARCHAR(100) NOT NULL,
    status      VARCHAR(20)  NOT NULL DEFAULT 'NOT_APPLIED',
    applied_at  DATE         NULL,
    jd_text     TEXT         NULL,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_applications_status CHECK (status IN (
        'NOT_APPLIED', 'ENTRY', 'DOCUMENT', 'FIRST_INTERVIEW', 'SECOND_INTERVIEW',
        'FINAL_INTERVIEW', 'OFFER', 'REJECTED', 'DECLINED'))
);
CREATE INDEX idx_applications_company_status ON applications (company_id, status);

-- ---------------------------------------------------------------------
-- 4. interviews
-- ---------------------------------------------------------------------
CREATE TABLE interviews (
    id              BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id  BIGINT      NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    round           INT         NOT NULL,
    scheduled_at    TIMESTAMP   NOT NULL,
    format          VARCHAR(20) NOT NULL DEFAULT 'ONLINE',
    result          VARCHAR(20) NOT NULL DEFAULT 'PENDING',
    notes           TEXT        NULL,
    created_at      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_interviews_app_round UNIQUE (application_id, round),
    CONSTRAINT ck_interviews_round  CHECK (round >= 1),
    CONSTRAINT ck_interviews_format CHECK (format IN ('ONLINE', 'OFFLINE')),
    CONSTRAINT ck_interviews_result CHECK (result IN ('PENDING', 'PASSED', 'FAILED'))
);
CREATE INDEX idx_interviews_scheduled ON interviews (scheduled_at);

-- ---------------------------------------------------------------------
-- 5. tasks
-- ---------------------------------------------------------------------
CREATE TABLE tasks (
    id              BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id  BIGINT       NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    title           VARCHAR(100) NOT NULL,
    due_date        DATE         NOT NULL,
    done            BOOLEAN      NOT NULL DEFAULT FALSE,
    created_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_tasks_application ON tasks (application_id);
CREATE INDEX idx_tasks_done_due ON tasks (done, due_date);

-- ---------------------------------------------------------------------
-- 6. ai_results
-- ---------------------------------------------------------------------
CREATE TABLE ai_results (
    id              BIGINT      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    application_id  BIGINT      NOT NULL REFERENCES applications (id) ON DELETE CASCADE,
    type            VARCHAR(20) NOT NULL,
    input_text      TEXT        NOT NULL,
    output_text     TEXT        NOT NULL,
    created_at      TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_ai_results_type CHECK (type IN ('JD_SUMMARY', 'QUESTIONS', 'AUTO_FILL', 'ES_REVIEW'))
);
CREATE INDEX idx_ai_results_app_type ON ai_results (application_id, type);

-- ---------------------------------------------------------------------
-- 7. part_time_shifts
-- ---------------------------------------------------------------------
CREATE TABLE part_time_shifts (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT       NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    workplace   VARCHAR(100) NOT NULL,
    start_at    TIMESTAMP    NOT NULL,
    end_at      TIMESTAMP    NOT NULL,
    memo        TEXT         NULL,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_shifts_time CHECK (end_at > start_at)
);
CREATE INDEX idx_shifts_user_start ON part_time_shifts (user_id, start_at);

-- updated_at trigger cho các bảng có cột này
CREATE TRIGGER trg_users_updated        BEFORE UPDATE ON users            FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_companies_updated    BEFORE UPDATE ON companies        FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_applications_updated BEFORE UPDATE ON applications     FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_interviews_updated   BEFORE UPDATE ON interviews       FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_tasks_updated        BEFORE UPDATE ON tasks            FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_shifts_updated       BEFORE UPDATE ON part_time_shifts FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- ---------------------------------------------------------------------
-- 8. Spring Session (lưu session đăng nhập trong DB)
--    Lấy từ schema-postgresql.sql của Spring Session JDBC
-- ---------------------------------------------------------------------
CREATE TABLE spring_session (
    primary_id             CHAR(36)     NOT NULL,
    session_id             CHAR(36)     NOT NULL,
    creation_time          BIGINT       NOT NULL,
    last_access_time       BIGINT       NOT NULL,
    max_inactive_interval  INT          NOT NULL,
    expiry_time            BIGINT       NOT NULL,
    principal_name         VARCHAR(100),
    CONSTRAINT spring_session_pk PRIMARY KEY (primary_id)
);
CREATE UNIQUE INDEX spring_session_ix1 ON spring_session (session_id);
CREATE INDEX spring_session_ix2 ON spring_session (expiry_time);
CREATE INDEX spring_session_ix3 ON spring_session (principal_name);

CREATE TABLE spring_session_attributes (
    session_primary_id  CHAR(36)     NOT NULL,
    attribute_name      VARCHAR(200) NOT NULL,
    attribute_bytes     BYTEA        NOT NULL,
    CONSTRAINT spring_session_attributes_pk PRIMARY KEY (session_primary_id, attribute_name),
    CONSTRAINT spring_session_attributes_fk FOREIGN KEY (session_primary_id)
        REFERENCES spring_session (primary_id) ON DELETE CASCADE
);
